INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','17','A','','ダンスが好き','なんでダンスがうまく見える？','見せ方がうまいから？','なんでダンスがうまい人がうまく見えるのか。ほかの人との違いは？','自分のとプロの動画を見比べる。友達にも聞く','体育、','ダンスをうまく見せるやり方がわかるようによさこいなどでも使えるかも','曲を決める。動画を集める','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','Ｓ','18','A','','料理が好き','なぜ料理を失敗するやつがいるのか？','多分料理の仕方が知らないのかも','どうしてレシピどうりに料理を作らないニンゲンがいるのか？','レシピどうりに料理を作らないニンゲンの意見を聞いてみる','視聴覚室','レシピどうりに料理を作らないニンゲンの意見を聞けるかも','レシピどうりに料理を作らないニンゲンの意見を聞く','レシピどうりに料理を作らないニンゲンの思考を読み取る','');
