INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','39','A','','サブカルチャーがすき','どうしてサブカルの良さに気づけない人が多いのか','わかる人にしか刺さらないし普通じゃない文化だから','本探求ではサブカルの良さや魅力を明らかにする','色んな魅力的なサブカルのアーティスト、作家、漫画家を調べる','社会、美術、音楽','サブカルを好きになる人が増えそう','インターネットで調べる。','サブカルチャーの魅力','');
