INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','12','B','','英語が楽しい！','なぜ日本の学校には英語の授業があるのだろう','もしかして世界で最も使われている言語なのかも。','本探求で英語がなぜ最も使われている言語なのかを明らかにする。','みんなが英語を喋れるために、簡単な言葉や勉強の仕方を調査する。','英語','みんな英語がうまくなって英語が楽しいって言ってくれるかもしれない。','自習をして自分に合う勉強法を調べてから、友達にどんな勉強法をしているか聞く。','英語をネイティブのように喋れる方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','13','B','','テニスをうまくなりたい','テニスがうまい人の特徴は','もしかして自分とは違う練習方法をしてるかも','自分の部活の練習方法と上手い人の練習方法を比較する','部活のコーチやネットで調べる','体育','テニスが上手くなるのと部活の練習方法が増えるかも','最初は練習方法を調べる','テニスの上達について','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','14','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','15','B','','亀が好き\!\!\!\!\!\!\!\!\!\!\!\!ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢','亀の種類などを詳しく知りたいð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢','もしかしたらめっちゃでかい亀の種類があるのかもð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢','本探求ではいろいろな亀の種類やとくちょう、飼っている亀のことを詳しく調べ、明らかにするð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢ð¢','みんなは亀が好きなのか、嫌いなのか、又はどちらでもないのか','理科','みんなが亀の魅力を知り、亀が好きになってくれる','まずは家で飼っている亀について','亀について','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','16','B','','おばさんは何故若いことにこだわるのか','そもそも若く見えるわけがないのに年齢を偽るから','若い頃の時代に戻りたいからかも','何故おばさんは若いころが一番記憶に残るのかを明らかにしたい','AIとかに聞く（おばさんとかに聞くのは失礼だから）','道徳','みんなが何故おばさんが若いことに執着するか知ってもらえるかも','僕のままに何故若いことに執着をするか聞く','おばさんたちは何故若いころに執着するのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','17','B','','今自分は何に集中するべきなのか','自分はダンスを習っているが、それは何のためなのか','','本探究では、','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','18','B','','今バスケにはまってる','バスケがうまい人の特徴','色々な練習方法があるかもしれない','シュートやドリブルをうまくなりたい','うまい人の練習方法を見る','体育','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','19','B','','音楽を聴くのが好き！集中力がない！(家での勉強が続かない！！)','どうしたら集中力を高めることができるのか','好きなこと(音楽)をしながらなら集中できるかもしれない！','本探究では、音楽を聴きながら勉強することで集中力が上がるのかについて明らかにする。','調べる。→実際にやってみる、試してみる！(家で)','音楽、保健','集中力が高まって、勉強ができるようになるかもしれない！家での勉強がはかどるかも！？','','音楽を聴くことで集中力が高まるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','20','B','','生物が好き','生物はなぜ生まれたのかその起源は何か？それはどこからやってきたのか？','もしかしたら宇宙からのウイルスが地球で進化して生命が生まれたのかも','この探求で、生物の原点が何かを知れている状態にしたい','生物学をある程度勉強し、て一番最初にいた生物について調べて考えていく','理科','人間や動物が何から生まれてきたのかが分かる。','いろいろな先生と話して、より良い調査方法を聞いて参考にして、調査をしていきたい。','～何もない時代からなぜ生命が生まれたのかについて～','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','21','B','','空を飛べるようになりたい','なぜ人は空を飛べないのだろう','飛行機の特徴に合わせれば、飛べるかも','本探求では、どのようにしたら空を飛べるかを明確にする','飛行機の特徴を調べ、飛行機に合わせていき実行してみる','理科','未来の空飛ぶ車を早く開発できるかもしれない','飛行機の特徴を調べる。','人は飛行機を真似したら、空を飛べるかもしれない','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','22','B','','生物が好き','なぜ生物についてわかっていないことが多いのだろう？','それだけ生物の進化が不思議なのかもしれない','本研究では生物の生態をちょっと明らかにする','実際に動物や虫の４体を集めて解剖する','理科','もしかしてだけどもしかしてだけそれって生物の何かを知れるんじゃないの','４体収集や解剖学について研究していきたい','ガ～ガキのやる解剖について～','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','23','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','24','B','','得意ではないけど地理とか歴史とかの国と国の関係が好き 宇宙とか地球の始まり気になる','小学生の頃はだいっっ嫌いだったのに何で急に好きになったのか？（社会）私がいるところはどれくらいの時間でできたのかな','私が好きになった理由は何だろう','どんな教科でも好きになれる方法を考える','中間検査があったのでそこで点数が高かった人にどんなやり方で勉強したかを聞く、楽しい教科のアンケートを取る。','社会','私が苦手な教科を克服し、学校に来る時の憂鬱が消え、考査の点数が上がる可能性がある。','','どんな教科でも好きになれる方法','');
