INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','6','B','','流行語の意味が分からん','なんで意味を知らなかったりするのに人は流行語を使うの','流行に置いてかれたくなくて無理やり使ってるのかも いうこと自体が楽しいのかも 感情を簡単に表せるからかも','流行語の意味や、本当に使うべき場面を見つける','ネットや、流行語の意味がちゃんと分かって使っている人に聞いてみる','道徳 国語 CT','流行語を正しい場面で使って、にわかと思われないようになる','ネットで流行語の一覧などを調べ、その中で学校で使っている人が多い流行語を抜き出す','流行語の正しい使い方','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','7','B','','たまごサンドっておいしい  空港のコンビニにたくさんたまごサンドあった','日本のコンビニのたまごサンドはなんで海外の人にも人  気なの','海外のたまごサンドと作り方とかが違うのかも','たまごサンドはなんで海外の人から人気なんだろ  日本と海外のたまごサンドの違いとか','調べる','社会英語家庭科とか','たまごサンドのすべてを知ることができそう','調べる','〇〇〇〇〇〇〇〇〇〇〇','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','8','B','','メイクおもしろい','メイクってどこの部分が大切なの','いくつかのところを意識してメイクしたら全体がよく見えるかも','メイクをするときにどこを意識したらいいか  メイクはどの部分が大切なのか','自分でメイクをしてどんなふうになったか  いくつかの部分を例としてアンケートを取る。','','いろんなメイクが知れる','どこの部分が大切だと思うのか','メイクはどの部分が大切なのか、どこを意識してメイクしたらいいか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','9','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','10','B','','漫画好き','なんで海外でも日本の漫画が人気になってるんだろう。どうやって流行っていってんだろう','テレビとかで紹介とかされてるのかも。もしかして飛行機や車にたくさんの漫画を入れて海外まで飛んで行ってるんじゃないか。','日本の漫画がなぜ海外に人気になっていってるのか。どうやって運ばれているのか','調べる。日本にも海外の漫画売ってあるのか見に行く','社会','・海外の人気な漫画を調べて海外の人と話せる話題が増えそう','本屋さんに行く','日本の漫画が外国にも人気な理由は？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','11','B','','日本の学校はどこでもチャイムが同じ','なぜチャイムはこの音なのだろうか','もしかしてチャイムを統一したほうが授業終わりのチャイムだと小学一年生などの小さい子供でもすぐ反応できるからだろうか','本探求では学校のチャイムの音が統一されてる理由と、他のチャイムについても調べて、理由を知る','Googleなどで調べる → 深く探究','社会、英語、国語','特に役立つことはないけど、雑学みたいに知識が増える','誤情報に騙されず、色々な情報を知る','学校のチャイムはなぜあの音なのだろうか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','12','B','','謎解きが面白い。','なぜ同じ学年でここまで謎解きに差が出るのか。','小さい頃の読書量？遺伝的要因？才能？','謎解きができる人の習慣について調べ、謎解きはほかの教科のように努力で点数が変わるのか。','謎解きが得意な人を探し秘訣を聞いてみる。また共通点を探す。','全教科。','謎解きにおいての点数を上げる。','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','13','B','','どうやったら１on１で勝てるようになるのか','どうしたら勝てるのか','ドリブルの技術力？','どうやったら１on１で勝てるようになるのか','必要そうなことを考えて、必勝法を探す','保体','','','どうやったら１on１で勝てるようになるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','14','B','','最近電子化が進んでるなあ','なんで紙じゃないんだろう。','めんどうだから？','本研究ではキャッシュレス化が進む世の中について調べたい。','紙が製造される行程について','社会','キャッシュレス化が進む世の中の流れを知れる。','インターネットで調べる。','キャッシュレス化が進む世の中のメリットとデメリットについて','');
