INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','20','C','','隕石が落ちる理由','本探求では、隕石が落ちる理由を明らかにする','インターネットで調べる、図書館で隕石についての本を探す、知っていそうな人に聞いてみる','隕石が地球に落ちる理由と、隕石の成分を明確にする。','知っていそうな先生に聞く、インターネット情報収集をする','特になし','理科、国語','国語：図書閲覧室','情報収集の最もわかりやすい仕方  考察の書き方  うまくまとめる方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','21','C','','ジャンプ力が高い人の特徴をインターネットで調べる。','本探求ではジャンプ力が高いは普段どんなトレーニングをしているのかを調べる','ジャンプとはどの体の部分を使うか調べる','ジャンプ力がない人の具体的な特徴を調べ底を改善する','次回に向けてインターネットで情報収集','特になし','体育、数学','保体①：体上','情報収集の最もわかりやすい仕方  考察の書き方  うまくまとめる方法','');
