INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','23','C','','SNSを通して起こっている事件、以前と比べた現在でのSNSの使われ方や歴史','本探求では、SNSの今に至るまでの成り立ちや、年々増えているSNS上での犯罪について明らかにする','SNSで何をすることが多いのかをアンケートし、その上で年々SNSでの事件が増えている経緯や理由について調査する','SNS上で犯罪が増えている理由を明確にする。そして、SNS上で起きている犯罪を減らすためにはどうすればよいのかを探求する。','クラスの人たちに調査する。  ①SNSをどのようなことに使っているか？  ②SNSは一日何時間使っているのか？（平日・休日）  （③AIに対してどのような印象を持っていますか？） （④SNSは今後どうなっていくと思いますか？）  また、ネットで情報収集する。','アンケートをFormsで集めたい。（持っていきたいもの・PC）','技術・歴史・保健体育（音楽・国語）','国語：図書閲覧室','Forms作成、Canvabaの準備、SNSについて調べる、My探求便利ツールの使い方の確認','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','24','C','','どうして三角や四角やバナナが貼ってあるだけの絵が売れるのか','どうしてそんな絵が売れるか明らかにする','どうやって絵につける色鉛筆それか絵具が作られたか，そしてどうして絵が作られたか','芸術は、爆発だっというけどどういう意味か明らかにする','インターネットを使う','タブレット、筆箱、紙、','美術','美術：美術室','プレゼンテーションを作る canvaを使いたいかも','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','25','C','','東京に高い建物がなぜ多いのか。また、高いビルなどを建てる時にどのような工夫がされているの。','本探究では、東京に高いビルや建物多いのかや、高い建物を建てる時に工夫しているところを明らかにする。','インターネットのいろんなサイトを使い情報を集め、集めた情報を整理する。','東京に高いビルや建物が多いのかを明確にする。','インターネットの情報を使う。','特にない','技術  （数学）','その他：視聴覚室','視聴覚室移動  パワポに情報を書き込む（それに少しつけか加えて完成させる）','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','26','C','','原外の国旗を作る','本探求では、過去の国々の出来事や、昔の国の国旗は今にどれくらい影響されているのか明らかにする。','歴史を知る…ネット、本  昔の国旗とどうやって作られたのかも調べる','調べた国旗たちの特徴をもとに原外に置き換えるとどんなことを国旗に入れられるか調べる。＝原外の特徴を調べる','「原外と言ったら」についてアンケートをとる  イメージカラーを考える','国旗の本','社会、美術','美術：美術室','パワポ仮作成','国旗ではなく校旗になるのでは？そしてそれはすでにあるのでは（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','27','C','','サッカーのシュートを上手くける方法、正確なパスを出す方法','目標を明確にする','シュート','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','28','C','','夜に携帯を見続けるのはどうしていけないのか','本探究では、夜に携帯を見続けるのはどうしていけないのかを明らかにする。','親がいうことやインターネットにかいてあったことを参考にしてインターネットを使って考える。','夜に携帯を見るとおこる悪いこととは何か','インターネットで情報収集。友達に、夜携帯をどれくらい使っているか調査する。また、何に使っているかも聞く。','pcの充電を満タンにしておく。事前に友達に調査しておく。','国語、道徳、理科（？）','国語：図書閲覧室','友達に調査したことをもとにパワポに調べたことをまとめながら進める。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','29','C','','どんな曲がどの層に刺さるのか知る。','本研究では、どんな曲がどんな時、どんな層に刺さるか知る。それを演奏に生かす','いろんな世代それぞれどんな音楽が好きか調べる','自分と同世代が好きな傾向にある曲を明確にする。  →その共通点なども明確にする','・友達、先輩に聞く  ・インターネットを使って調べる  →・歌詞や曲の速さ、ボーカルの種類などを調べる  →・一番多い傾向にあった特徴をまとめる','友達10人くらいに聞いておく  今回使うかはわからないけど、どんな曲か知るためにスマートフォンなどの電子機器が必要になることがあるかも','音楽、社会、国語','音楽：音楽室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','30','C','','0','本探求では、なぜ人気なのかと、なぜ嫌いな人がいるのかを知る。','いろんな人に好きなのか聞く。嫌いだったら、なぜ嫌いなのか、好きだったらなぜ嫌いなのかを聞く。','美味しいと感じるのはなんでか明確にする。温度だったらどっちのほうが人気なのか','サファリで調べる。抹茶は冷たいのと温かいのどっちが人気なのか調べる。','親などに抹茶はなんでおいしいと感じるのか、また、どちらのほうが美味しいと感じるか聞く。','社会、理科','理科：第１理科室','キャンバ作成','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','1','C','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','2','C','','漫画とかアニメってなんであんなに止まらないんだろう．．．','本探求では、なぜ日本の漫画、アニメはおもしろい\!\!素晴らしい\!\!と言われているのかその理由を明らかにする','実際に海外の漫画を読んでみて、日本の漫画と比べてみる','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','3','C','','スクラッチで3dを作る','https://scratch.mit.edu/projects/1310768914','https://scratch.mit.edu/projects/1310768914  の中身を解析追加ライブラリ,apiを使用してるかを見る','','','','技術、数学','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','4','C','','絵がうまい人の絵を分析してみたい','自分に合う絵の描き方を見つけたい。','絵がうまい人の絵の分析、絵の技法を調べる','図書館に行って美術の本を読む 美術館に行く インターネットとかで絵が上手になるような方法を調べる 自分にっとて絵が上手な人をまねて絵をかいてみる','絵の特集みたいなものを買う・自分で絵がうまい人の共通点を知る、分析する ・自分はどんな絵を描きたいのかを知る','お金 調べるためのスマホ','美術','美術：美術室','絵を調べよう、自分が似せてみたい絵を見つける、好みを見つけよう','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','5','C','','今の自分のシュートの確率が知りたい','シュートを10本打ったら7本くらい決めれるようになりたい','毎日シュートを百本打つ確率が上がってきたら百本決るようにする','一個一個のポジションでシュートを十本ずつ打って確率を出して自分の苦手なところを見つける','毎回My探究の時間に百本ぐらい打って確率を出していくそして終わるころにドンぐらい確率が上がるかをじっせんしていく','ボール、ゴール、まとめるようのかみ,バッシュ、水筒','体育、数学、理科','保体①：体上','次のサイクル位置で五か所のスリーとミドルを十本ずつ打って（合計百本）記録をまとめる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','6','C','','バレーが上達する方法','・','同じバレー部の人、先輩や、タブレット、本で調べる','自分の間違っているフォームなどを知って改善点を見つける','先輩や上手い人、コーチに聞いて間違っているところを見つける またネットで情報収集したりバレーの試合のどうがをみたりする','シューズ サポーター 調べるタブレットや本','体育、保体？','保体①：体上','なし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','7','C','','人間に効果的な食事について考える','本探究では、食事と人間の心と体の関係について明らかにする。','・みんなに調査する  ①食事することでどんな良いことがあるのか  ②どんな食べ物、料理を食べると幸せな気持ちになるのか？  ③どんなときが一番美味しく感じる？、どんなときおなかがすく？  ④どんな食べ方をすればもっと効果的になる？…など  ・毎日自分の感情をチェック！→どんなときおなかがすく？どんな良いことがある？どんな食べ物が幸せになる？どんな見た目、においが良い？など。付箋などに書き出し整理・分析、考察をする。','人間にとっての食事について明確にする。  →役割、心、感情、効果、改善について！  自分の食事に対する気持ちをまとめる。','・アンケート  ・インターネット  ・本  ・自分の心','本','家庭科、保体、理科（？）','その他：視聴覚室','From作成（質問することを考える）  家で、食事するとき、するまえ、したあとの感情をメモ。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','8','C','','ラクトアイスとは？？  体に悪いと言われているのは本当？','本探究では、ラクトアイスが体に悪い場合、その理由を明確に、客観的に、説得力がある発表をする。  また、メリットも調べる。  また、体に悪い理由は、他のアイスより栄養素が取れないなどの問題もあるかもしれないから、他の3種類の栄養素を伝えるために、他のアイスも調べる。','アンケートを取る。  調べたことを分かりやすくグラフにまとめる。','・アンケートを取る。  ・値段やカロリーなどを調査する。','・アンケートを取る。  →「一番好きなアイスの商品名は？その理由は？」「ラクトアイスにどんなイメージを持っている？」  ・実際にアイスを買い、値段やカロリーを調査する。  →結果的に、ラクトアイスは体に悪いのか、悪い場合、なぜ悪いのか、またメリットも調べる。','アンケートをFormで作る。','理科（？）、保健','その他：視聴覚室','Form作成、プレゼンの構成→写真','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','9','C','','ドラムを演奏できるようになるには、ドラムのプロはどんなことをしているのか','本探究ではプロの練習方法や、リズムの取り方、演奏方法などを明らかにする','そのためにドラムのプロの人がどんなことをしているか分析する','ドラムを演奏できるようになる→バンドをやって演奏したい（聞いてもらいたい）','演奏のコツを知る  プロの人がどんな練習方法をしているか、どんな演奏をしているのか研究する','スマホとドラムの使用の許可をラボの先生にもらっておく','音楽','音楽：音楽室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','10','C','','確率を調べる','本探求では、なぜ自分がみんなと違って3ポイントが入んないのとみんなのシュートホームや角度が違うのか','コーチやうまい人にどういう風に打っているのかを確認する','シュートを打って確率を確かめ何が違うか見る。','シュートホームを確認してみんなより入りやすくする','ボール、ゴール、タブレット、紙、バッシュ','数学、理科、体育','保体①：体上','３ポイントとミドルのを5か所の場所でシュート打つ。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','11','C','','ベースをうまく弾くコツ、魅せ方はなにか、音楽のおいてのベースの役割、魅力とは','本探求では、ベースをかっこよく魅せるには、音楽でベースが必要なのはなぜ？','ベースの弾き方魅せ方を調査し、もしできたら楽器関連の人とバンドをやって魅力を伝える！','ベースの魅力を伝えるためバンドをやりたい','ベースのコツ、かっこよく見せる方法を調査する。実際のライブ映像を見てどんな感じなのか調査する','スマホ,イヤホンを使ってライブ映像を見たり、曲を聴いて調べたい、ベースを持っていきたいラボの先生に許可をもらっておく','音楽','音楽：音楽室','スマホを使う、ベースを持ってくる許可をもらう、魅力を調べる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','12','C','','サックスを上手くするためには','本研究には、プロの吹き方の共通点を明らかにする','そのために、いろんな人の吹き方や練習方法を比べて違うところと共通点をまとめる','吹部のサックスのコーチと調べてみたサックス奏者の特徴を比べる','サックスのコーチが吹いているところ(アルト・テナー)を見ていろんな人と比べ自分でも吹いてみる','買えたらテナーサックス・スマホ','音楽、理科？','音楽：音楽室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','13','C','','無回転やカーブはどうしたら蹴れるか？','全体的に足の筋肉を鍛えて無回転やカーブは蹴れるか。 何度も蹴って改行を重ねたら無回転やカーブは蹴れるのか。','プロのサッカー選手のシュートを見る。無回転やカーブの解説動画を見る。','','','自スパイク','体育 数学 理科','保体②：校庭','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','14','C','','自分の作ったアニメをどうしたら見てもらえるか。傾向にのれるか（傾向とはscratch内の見られている人気のランキングのことである）','','','みんなに見られるために、どんなものが魅かれるか、','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','15','C','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','16','C','','作品を作っている人たちが私たちの興味を引く方法は？？','本探求では物語を作る際に大切なことについて明らかにする','そのために、作品を見たときにどう思ったか、何に引き付けられたか、なぜその物語を見始めたかなどを、友達に聞いてみる。また自分が気になった物語も調べてみる。','出来るだけいろんな人の好きなアニメを聞いてみんながどんな理由でどんなアニメが好きなのかを集計する。','アンケートを作ってみんなに説いてもらう、またそれを集計してどんな特徴があるのかを調べる','アンケートを作る、先生に許可を取る、調べて分かったことをまとめるなど','\#VALUE\!','国語：図書閲覧室','どんなアンケートを作るか  好きなアニメはなにか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','17','C','','人間の感覚はどのようにかんじるのか','可愛いと思う気持ちについてもうちょと知りたい','もっともっとかわいいとは何かについて知りたい','','Googleなどを活用してｍうぃかくににんげんのかんじょう、かんかくについてしらべる','ない','理科','理科：第１理科室','ない','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','18','C','','原宿や渋谷はなぜ若者の町として有名なのかと、それにつながる流行','本探究では原宿の魅力とファッションの繋がりを明らかにする\!\!','原宿の歴史を調べたり、今のはやりとかを知って、それがどんなファッションにつながっているかを調べたり、聞いてみる','原宿の歴史を調べて、現代でも残ってる魅力?を探す','Googleで歴史を調べたり、人に原宿の好きなところを聞く','チームスでアンケートしたいから先生に許可をとったりする','社会 美術 家庭科','社会：２A教室','アンケートの作り方と投稿していい許可','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','19','C','','サッカーでキックの精度、威力をうまくする方法は？','本研究ではサッカーのキックで無回転のけりかた回転のかけ方を調べたり、どんなキックがあるか調べ、逆足の精度、威力を上げる。','グーグルで調べる。サッカーの解説のサイト？を調べる','キックの種類を調べたり、逆足がうまくなることを調べる','調べた結果から実際にけってみる','','(2)''\!L111','保体②：校庭','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','20','C','','脳の仕組みについて知りたい！','脳がどうして頭の中で喋れるのかを明らかにする。','脳の働きについてのサイトを調べてみたり、体の器官について詳しい人に話を聞く。','脳の仕組みについて知り、自分の思考や感情をコントロールできるのが最終ゴール。','タブレットで脳の仕組みについて書かれているサイトを探し、探求の参考にする。体の器官について詳しい人に話を聞く。','タブレット、自分の本の持ち込み許可をとりたい。','理科','理科：第１理科室','タブレットの充電を満タンにしておく！脳の仕組みについて乗っている本を購入する！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','21','C','','バレーボールがうまくなるコツ','本研究ではバレーボールがうまくなるためのコツを明らかにしたい‼！','そのためにバレーボールをしている時にどのようなことを考えてやっているのか、初めてバレーボールを始めたときは何を意識してボールを触っているのかを聞いたり考えたりする。','うまくなるコツはなんなのか、、どうしたら調べられるのかを明確にしたいna～','先輩やコーチにどうしたらそんなにうまくなれるのか、いつも教えてくれていることもしっかりと覚えている。そしてネットを使ったり、本を読んだりする。','調べたものをパワーポイントにまとめたり、タブレットやシューズ・ボール・サポーター仕組みを調べる。 なのでボールはそのラボの先生に使ってもいいのか許可を取る。','保体・体育・国語（考える）','保体①：体上','ボールの許可を取ること','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','22','C','','フィギュアスケートの回転のかけ方と種類はいくつあるのか','本研究では回転のかけ方の種類と、どのかけ方がよいのかを調べる','そのためには回転のかけ方の種類と、どのかけ方がよいか、自分に合っているかを考える。','回転のかけ方の種類は何個あってどんな特徴があるのかを明確にする','回転のかけ方についてネット情報収集をする。スケートの友達に聞く','タブレット・室内靴','国語（まとめる）保健？体育','保体①：体上','ない','絞る際に、腕の位置が胸の前なのか、クロスなのか。ジャンプも高さを出すのか距離を出すのか、それぞれ違うので、多様な観点で調べてみてください（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','23','C','','面白い動画はどういう共通点があるのか。','本探求では制作の裏側を知る。','いろいろな動画の中で一番再生回数が高い動画を見てどういうところが面白いのか他の流行っている動画と共通点があるか見てみる。','面白い動画の秘訣を明確にする！！','日常組を知っている人にどの動画が一番面白かったか？聞く','タブレットの許可をもらう','国語、社会？','国語：図書閲覧室','一番上と同じ意見でExcelを学ぶ','裏側だけでなく、構造を調べても良いのでは？例えば、何分ごろに何が起きるとか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','24','C','','自由自在に雨を降らせたり、逆に雨をやませたりすることはできるのか？？','本研究では、家の中で自然現象を起こすことができるのか仮説を立て実験し、どのような良い影響をもたらすのか考えて、報告する。','もしかしたら、家の中でも雨を降らせたり、竜巻をおこしたりすることができて、家の中でも農業ができるようになるのかもしれない。砂漠にも雨を降らせることができるようになるかもしれない！！','家の中で、雨が降るのか。どうしたら雨が降るのかを明確にする。','塾のテキストや、教科書を基に雨について調べてみる。ほかにも、なぜ雨が降らない地域があるのかなども考えて、調べ、実験する。','・三木先生に、薬品の許可（実験の時）を取る。もしかすると、外部の人と連絡を取る許可ももらうかもしれない。  ・【持ち物】塾のテキスト、タブレット、理科室の備品（ビーカーやフラスコ）など。','理科（科学）','理科：第１理科室','Excelの使い方を知る。事前のリサーチをしておく。','理科ラボで、雨が降る条件などを（テキストなどで）分析し、仮説を立て、実験する。');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','25','C','','サッカーでキックの精度、威力などを上げる','本探求では自分がどれだけ蹴れるかを明らかにする。','プロのサッカー選手のシュート動画を見る','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','26','C','','バスケットボールの知識を得たい','本探究では自分の今の知識から色々な知識に成長させたい','','知識を得てそれを覚える。','ネットで調べる、バスケットボールが上手な友達に聞いてみる','キャンバもしくはパワポでバスケ用語などを発表。実行したことの発表','体育','保体①：体上','ない\!\!\!\!\!','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','27','C','','バレーボールがうまくなるには。','本研究では、パスやサーブをうまくなるためにやり方を調べることと実際に試す。','アンダーやオーバーの仕方を調べる。実際にサーブ、スパイク、アンダーとオバーをやって自分は何をしたらもっとうまくなるのかを分析する。','試合やうまくなるためにアンダー、オーバー、スパイク、サーブ、ブロックのコツを知る。','先輩やコーチに教えてもらう、コツを調べる。（タブレット）','シューズ、サポーター','','保体①：体上','ない','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','28','C','','バレーボールが上手くなる方法を知る','本研究ではパス・トス・サーブ・スパイクの上手くなるコツを知り、練習する\!','コーチなどにどのようにやっているかを教えてもらい、上手くなる方法を調べる','パス・トス・サーブ・スパイクの上手くなるコツを明確にする\!','タブレットで情報収集をしたり、コーチや上手い人に聞く→実際に試してみる','・シューズ・サポーター','体育・国語','保体①：体上','ない','');
