INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','25','C','','バンドの中の重要性や楽器の役割について','本探求ではバンドの楽器の役割やバンドにおいて必要なこととは何かなどバンドに関する気になることをいろいろな視点から明らかにする','各楽器の音色や役割を明らかにする','バンドの中の各楽器の役割と音色について','インターネットで調べる','なし','音楽','音楽：音楽室','','');
