INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','4','C','','日本犬の特徴と歴史','日本犬のとくちょうとれきし','日本犬について調べる','絶滅した日本犬と絶滅しなかった日本犬の歴史を調べて違いを調べる','インターネットでしらべる','なし。','社会','社会：２A教室','特になし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','5','C','','宗教、文化がたくさんある理由と','なぜ宗教に種類があるのだろう','宗教の種類、文化の種類、さまざまある理由','宗教、文化がもたらすいい面と悪い面','戦争を起こさないためにシュミレーションゲームなどで止めてみる。','スクラッチをやる','社会、外国語','社会：２A教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','6','C','','注射の年齢制限について','年齢制限がついている理由を調べる','調べる・病院のホームページ','注射の種類ごとに調べる','サイトを見る','','0','社会：２A教室','','新生児でも打てる注射もあります。打てる注射と打てない注射についてリサーチし、どうすれば新生児や幼児でも打てる注射ができるのか、開発してみても良いのではないでしょうか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','7','C','','日本と海外の漫画の違い','日本漫画と海外漫画の違いを調べる','ストーリー、絵、ジャンルの違いを比較する','','','なし','社会、国語、美術','社会：２A教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','8','C','','なぜユダヤ人は世界で嫌われてきたのか','ユダヤ教の信条を調べる。','イスラム教・キリスト教と比較して表にしてまとめる','一神教か多神教か、戒律の違いなどをインターネットで調べる。','インターネットで調べる','なし','社会','社会：２A教室','ユダヤ教、イスラム教、キリスト教はすべて一神教｡ヤハウェとアッラーは同一の神であるとされている。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','9','C','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','10','C','','集中が切れる原因と集中して勉強できる方法は','本探究では集中が切れる原因を調べて集中できる方法を明らかにする。','集中力に関係していることを調べて原因を考えてそれをもとに集中力が上がる方法を考える','集中力が切れる原因をインターネットで調べる。','分かったことをもとに集中力を保ったままできる勉強方法を考えてやってみる。','なし','体育','その他：視聴覚室','','インターネットで調査したうえで実験してみてはどうでしょうか。集中力が向上・もしくは低下する条件と、そうじゃない条件の2パターンで計測し有意差が出るか検討してみても良いのでは（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','11','C','','クッキーやマドレーヌなどの焼き菓子を、味も見た目も良く作る方法は？','本探求では、家にある道具で、味も見た目も良いお菓子の作り方を明らかにする。','作る時のコツを調べ、実際に試してみる。','インターネットや本を使って、焼き菓子を作る時のコツを調べる。','インターネットや本などで得た情報を基に、実際に家で作ってみる。','タブレット、お菓子作りに関する本','家庭科','国語：図書閲覧室','','今年は家庭科選択できなかったはずなので、別の方法からアプローチしてみてはいかがでしょうか。例えば、一流のパティスリーは造形にも非常に強いこだわりを持っています。どのようにしたら美味しさと造形の両立をできるか、検討するとか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','12','C','','長距離が早くなるコツ','部活だけではない努力があるのではないのか','長距離が早い人の特徴','速い人のアドバイスを受ける','まずは普通に1500ｍを走る。でアドバイスをもらってメニューを立ててまた1500ｍ走る','自分、靴、タイマー','体育','保体②：校庭','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','13','C','','なぜ植物でも「花」には色があるのだろう','葉っぱに入っている成分とほとんどの花に入っている成分を比較する。','葉っぱの成分とほとんどの花に入っている成分を調べてノートなどにまとめて、比較する。','理科の先生に聞いてみる。','インターネットで葉っぱと花の色が違う理由を検索してみる。','花、木の葉っぱ、土、植木鉢','理科','理科：第１理科室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','14','C','','スマホ依存症について','スマホ依存症の原因','ネットで調べた改善点をやってみて、スマホから抜け出せるか','とりあえず三木先生。','ネットで原因と改善点を調べる。','田ブレ','理科？','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','15','C','','体感時間を調整するには？','本探求では、体感時間と集中・運動時の関係性を明らかにする。','運動中、集中しているとき、退屈な時、楽しい時に脳や体にどんな変化が起こっているのかを調べる。それぞれのときに体感で5分か10分計って誤差を記録する。','体感時間と楽しい時、退屈な時、集中しているとき、運動時の関係性を明らかにする。','楽しい時、退屈な時、集中しているとき、運動しているときに脳にどんな変化が起きているのかタブレットで調べる。それぞれの時に体感で5分か10分計って誤差を記録する。','タブレット','理科、数学、家庭科、体育','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','16','C','','サッカーの','','','','','','皇帝','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','17','C','','音楽の誕生、その進化の軌跡','本研究は音楽がどのようにできて、どのように進化したのか','音楽の誕生、その進化の軌跡を調べる','音楽がいつ、どのように誕生したのかを調べる','Googleを使って誕生した年、どのようにかを調べる','ない','音楽、社会','社会：２A教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('9','A','47','D','原宿 外苑','℃流行の曲予測','','心に響く歌詞・フレーズを調査しランキング形式にする','「心に響く歌詞・フレーズ」とは何か明確にする','「好きな歌とその歌詞」について50人くらいに聞く。また、ネットで情報収集する。','アンケートをFormで集めたい。ラボの先生に許可をもらっておく。','音楽、国語、社会、数学','音楽室','Form作成、許可をもらう、Excelの使い方','人間が好む特定のリズムがあるのではないか？音楽で実験してみてはどうか（◎◎）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','1','D','','0','','','','','','0','美術：美術室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','2','D','','長距離はどうしたら速くなるのか','本探求では長距離の歴史を知り、長距離はどうしたら速くなるのかを明らかにする','長距離選手の動画を見て自分とは何が違うのかを知る','・1500ｍを計算する ・何回か測って、まず最初は今の自分のタイム、2回目以降は天候や体調、長距離選手のフォームを気にしながら測る。','有名選手の走り方を真似する','特になし','保険、体育、数学','保体②：校庭','まずは何も見ないで走る。体調などを記録する。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','3','D','','0','','','','','','0','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','4','D','','成長期が終わるまでに身長を伸ばすには？成長期が終わったら身長は伸ばせるのか,成長期とそれ以外では身長の伸びる変化はどのくらいあるのか','運動、「食べ物」、「生活」、DNA、遺伝子などが関係するのかも','身長はどんなことと関係するのか（運動、「食べ物」、「生活」、DNA、遺伝子など）、身長を伸ばすためにはどのようなことをするのが大事なのかを調べ実行する。3か月でどのくらい伸びてるかグラフにしてみてみる','身長を伸ばすためには何が関係するのかを明確にする。それを実行する「調べて出てきた効果（例ジャンプをすれば身長が伸びる）」','運動、食生活、DNA、遺伝子、成長期のタイミングが分かる方法を調べ関係するのもを明確にしたら、これらのことから身長を伸ばすためには何をすればいいのかを調べ実行できそうな物から実行する。そのあと身長を図ってみて身長がいつもより伸びているか比較をする。身長が伸びていなっかった場合改善点を探す見つかった改善点について調べ実行することを繰り返す。またこれらのことをほかの人にもやってもらい自分の結果を比べてみる「その人の親の身長なども注目してみる」','','保体、数学、理科','国語：図書閲覧室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','5','D','','0','','','','','','0','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','6','D','','スポーツがより良いものになるためには  どうすればいいか考える。','本探求では色々はスポーツ起源やルール、なぜ考案されたかを明らかにし、  自分が好きなスポーツ以外でのスポーツで楽しさを見つける。','アンケートやそのスポーツについてどう思っているのかを調査する。','そのスポーツの起源の場所と最初のルールからどのように進化したかを明確にする。','皆の好きなスポーツをアンケートで調査する。','Formを作る。','体育、社会「歴史」「地理」','保体②：校庭','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','7','D','','地球を変形させたら人類や地形、重力はどうなってしまうか考える。','本探究では地球の形を様々にし、どんなことが起きるのか明らかにしたい。','みんなが住んでいる地球がもし丸じゃなくて様々な形になったらどうなるのか、まず重力について調査したい','地球を様々な形にし、人や地形はどうなってしまうのか明確にする。','便利ツールやサイトを使い一回一回まとめをしながら調査する','パワーポイントなどに調査したことをまとめる。','理科 天文学','理科：第１理科室','0','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','8','D','','埼玉県で住みやすい、市区町村を見つける','本探求では埼玉県のうち暮らしやすい市区町村を考える','住みやすい基準を明らかにして','８地方から１地方を選びいろいろな観点で暮らしやすい都道府県を調べる','まずは８地方のうち１地方をきめてそのすべての都道府県の自然の割合、交通網、などいろいな観点から暮らしやすい都道府県を調べる。','WordやPowerPointなどでまとめる。','地理 数学','社会：２A教室','どういう方法でまとめるか考える。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','9','D','','絵のバランスをとれる普段の行動を調べる。','本探求では、普段やっているだけで、絵のバランスが取れる方法を見つける。','普段の行動で、絵のバランスがとれるようになることがないか調べる','身近なもので、絵のバランスが取れるようになる方法を調べる','','・筆記用具・紙「スケッチブック」','美術、国語、社会、CT','美術：美術室','方法を調べてから、実践する。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','10','D','','バスケが強くなる方法をしらべる','シュートが入るようにする','シュートについて調べて、調べる前と調べた後でシュート格率を比べる','自分に合うシュートホームを見つける','NBAのプレイヤーのシュートホームを真似してみたりユーチューブが入る方法を調べたりする','バスケットボールと体育館','保健体育','保体①：体上','','');
