INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','12','D','','英語のネイティブになる方法','本探求では英語をどうやってネイティブにしゃべるかを明らかにする','英語をしゃべっているとき口の中、舌の形はどうなっているのか。','英語をどう喋ればネイティブになるか明確にする。','お父さんが元英語の先生だったのでどうやって教えればネイティブになれるか聞く。そして、ネットや本でも調べる。','英語の本やワークブックをやる。お父さんに聞いて見る。','英語','英語：１D教室','お父さんに聞いたことや本、ワークブックのことをノートにまとめる。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','13','D','','テニスの上達のコツ','上手い人の練習方法とその人の試合の動きを明らかにする','コーチやネットで調べる','上手い人の動きや意識していることを明らかにする','上手い選手のテニスの上手くなるコツなどの説明をネットで探す','タブレットの使用の許可','理科 数学 保体','国語：図書閲覧室','許可をもらう 上手い人の動きと特徴を調べる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','14','D','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','15','D','','亀について','みんなは亀が好きなのか、嫌いなのか、又はどちらでもないのか','自分が飼っている亀を詳しく調査し、亀全体について詳しく分析する。','亀について明らかにする','亀が好きか嫌いかアンケート調査をし、インターネットで亀について詳しく調べる','Formを使ってもよいか','理科','理科：第１理科室','Form作成、許可をもらう','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','16','D','','おばさんはなぜ若いころに執着するのか','何故おばさんは若いころが一番記憶に残るのかを明らかにしたい','やっぱ本物のおばさんのママに聞くのがいいからママに聞く','ママにインタビューして理由を明らかにする','ネットなどでおばさんがなぜ若いころに執着するのか調べる','','道徳','その他：視聴覚室','','果たして全員が若い頃に執着しているのでしょうか。中には、年齢を重ねた今が一番美しいと感じている方もいると思います。前提条件を見直すか、若い頃の方がよかった人と、今の方がよかった人で比較するとよいのではないでしょうか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','17','D','','人にヒットする曲にはどんな秘密があるのか','本探究では、人にヒットする曲の特徴を調べる','身近のお友達や先輩に好きな曲やアーティストを聞きに行く','人々に刺さる歌詞やメロディーを明確にする','お友達や先輩に好きな曲やアーティストを聞いたり、ネットで調べる。','スマートフォンとイヤホン','音楽、国語、英語','音楽：音楽室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','18','D','','バスケにはまってる','うまい人の練習方法をあきらかにする','うまい人とかにきいたりして実際にやってみる','','まず一旦やって駄目だったところは聞いたり調べたりする','特にない','体育','保体①：体上','バスケのシュートの仕方を調べる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','19','D','','どんなジャンルの音楽が集中力を高めるのか','本探究では、集中しやすい音楽のジャンルは何かについて明らかにする！','調べる。→実際にやってみる（どのジャンルが集中しやすかったかについても）','音楽を聴くことで集中力が上がるのか、どのジャンルが個人的に集中しやすいかについて明確にする。','ネットで情報収集、本で調べる(集中力について、集中力があがるのか、音楽のジャンルなど) 実際に家でやってみる(どのジャンルが一番集中しやすいか)','','音楽、保健','国語：図書閲覧室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','20','D','','0','本探求では，生物が何から進化してきたのかを明らかにしたい','','','','','0','理科：第１理科室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','21','D','','人間の体の特徴と飛行機の機体の特徴の違い','本探求では、人間の空の飛べない理由や、逆に飛行機の飛べる理由を明確にする。','人間の空の飛べない特徴と飛行機の空を飛べる特徴を比べる','人間の空を飛べない理由、飛行機が空を飛べる理由を明確にする。','本で調べる。理科の先生や、技術の先生に聞く。また、ネットで構造を調べる。','人間、飛行機の本を選んでおく。','理科、技術','国語：図書閲覧室','本を選ぶ。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','22','D','','生物学を解剖する','本研究では、生物学についてちょっと深め、発見する','それぞれ昔からいる動物（ゴ〇ブリやミミズなど）と脊椎動物（カエルなど）を解剖して体の中を比べる','解剖学やどうやって解剖すればより深く理解することができるか','メスで4体を解剖し、虫などの小さな生物の場合は顕微鏡で体の内部を確認する','メス、ルーぺ（微妙な大きさの時）、動物','理科（生物学）','理科：第１理科室','許可をもらう、身近にいる虫たちを集める（my探求の時には4体状態にする）','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','23','D','','0','','','','','','0','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','24','D','','どんな教科でも好きになれる方法','¥','中間検査があったのでそこで点数が高かった人にどんなやり方で勉強したかを聞く、楽しい教科のアンケートを取る。','今の中間考査とこの探求が終わった後にやる考査の結果を比べて（苦手な教科）成果を見る','自分は何で好きになれたんだろうと追及してみる、一つ一つの教科の得意な人にどのようなところが好きか好きになった経いを聞いてみる。','アンケートを取るのはありか、探求中ほかの人に直接聞く（アンケートを取る）のはありか','社会（教科全般）','社会：２A教室','許可の確認をする','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','25','D','','ーーーーーーーーーーーーーーーーーーーーーーーーーーーーー','バスケ‼','','','','','0','保体①：体上','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','26','D','','体が柔らかくなる方法！！','本探究では、体が柔らかい人と硬い人はどのような違いがあるのか？','googleで、柔らかくなる方法を調べて、実査に試してみる','友達などに聞いて違いを見つける。','「体が柔らかくなる」','','0','国語：図書閲覧室','','例えば、足が高く上げるためには股関節の柔軟性が大事だと思われがちですが、太ももや腸腰筋のストレッチが大事です。このような筋肉のつながりについても調べてみるとよいと思います（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','27','D','','0','','','','','','0','美術：美術室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','28','D','','バスケのシュートと、ドリブルを、上達させたい！！','本探求では、バスケのシュート率を上げるフォームドリブルのコツを明らかにする','そのために、プロの動画を見たり、中学一年生のバスケの大会の動画を見た','プロのフォームや、うまい人のフォームを研究したい','','','0','保体①：体上','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','29','D','','日本語と中国語の違い','','','本かタブレットで中国語と日本語の違いを調べる','','','国語','国語：図書閲覧室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','1','D','','心理テストが本当に当てはまるものなのか','本探究では当てはまっていない人がいるのか、なぜ当てはまっているのと思う人がいるのかを明らかにする','友達に心理テストをやってみて当てはまったか、当てはまっていないかをアンケートを取る。本当に当てはまっているのかを調べる','なぜ心理テストは当てはまるのかを明確にする','心理テストの種類を調べる。友達に心理テストをやらせて、当てはまったかどうかをアンケートを取る。結果どの心理テストが一番当てはまった人多かったのを徹底的にしらべる','クラスのチームスにアンケートを送ってもいいか','数学、道徳','その他：視聴覚室','','心理テストには、バーナム効果というものもあります。調べてみて下さい（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','2','D','','0','本研究では、うまい人がどういう練習法や、サーブの仕方をしているのか明らかにする。','うまい選手やプロのやり方をよく観察する。','プロやコーチの綺麗なフォームを研究したい','選手のフォームが詳しく乗ってる動画を見る。考察をすかししてみる。','プロの動画やコツを調べられるもの。ブロックされないやつとか。ボール、コート、スマホ化タブレット、','保体、実技','保体②：校庭','プロ選手のフォームの動画見ること','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','3','D','','左利きになったらどれほど生活が楽なのか','本研究では右利きの人から両利きになれるかを明らかにする','左利きの人を観察あと、バスケも左を使う','両利きになるまで毎日トレーニングをする','何回も言うけど左利きの人の動画または実際に見る','お箸・お茶碗','保体・国語・家庭科','保体①：体上','','一般的には左利きは不利だと考えられます（例：ハサミ・習字など）。あえて、左利きが有利になりうる場面に絞って考えてみても良いのではないでしょうか、サウスポーとか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','4','D','','サッカーのうまい選手たちが、どのようにボールを扱っているのか、について分析する。','本探求では、プロの選手たちがどうやったボールの持ち方をしているのかを明らかにする','プロのうまい選手たちがボールを持っている時の足元や顔の上がり方、どうやって相手を抜きにかかっているのかを分析をする。','プロの選手がドリブルをしている時に、どうやった顔のあげ方をしているのかどういう体の向きをしているのか、について研究する。そしてそのプレーできるためには何をすればいいのか明確にする。','ドリブルがうまい何人もの選手のプレーを何度も見て、顔の上がり方や抜く時のクセ体の方向などを研究する。','・サッカーシューズ ・ボール ・タブレット ・３B教室また校庭の２か所の使用の許可','体育、数学、理科','数学：３B教室','・選手ドリブルの仕方を調べる ・ラボ２か所の使用許可を取る','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','5','D','','インターネットに対する人の欲とは','インターネットの発展により浮上した問題はなにをすれば正しかったのか、それとも必然的に起こってしまうものなのかを明かす','世間がインターネット中毒などの問題に何を思い、どう向き合っているか。身近な人にも聞き、調べる','人は何を思い、インターネットを使うのか 人の欲について明確にする。','人の欲についての本を読む。身近な人（親やクラスメート）になぜインターネットを使うのか インターネット中毒を防ぐために何かしていることはあるか。 を聞く','特になし。アンケートは個人で行う。必要であれば、アンケート用紙','図書、道徳歴史','国語：図書閲覧室','ラボのみなさんにアンケートを取っていいか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','6','D','','バスケチームを作って優勝を目指せるチームにするにはどうすればよいか','本探求では、バスケチームを作るまでの工程を調べる。','日本のバスケリーグ、海外のバスケリーグを見て、どんな共通点があるか調べる。','強くバランスの良いバスケチームの共通点を見つけて一番良いチームを見つける','直近５年間のNBAチャンピオンを見て主力選手の特徴をまとめる。選手だけでなく監督なども見てみたらもっと良いかもしれない。','特にない。','体育、数学','保体①：体上','過去５年のNBAチャンピオンをまとめる。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','7','D','','0','本探求では、K-popがどのように広がっていってなぜ人気なのか、K-popグループの傾向を明らかにする。','そのためにK-popの歴史について詳しく調べる。K-popをもとに流行るものとかも多いから、どうして流行りをつくれるのか、どんな傾向のグループが人気なのか調べる。過去の人気になった例をスライドに乗せる','・いろんな過去のグループを見る   ・どんな流れで流行りが作られたのか','過去のグループの特徴をまとめて表とかにする','タブレット、筆記用具、紙','体育、音楽、歴史、道徳','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','8','D','','ギターにあこがれた','ギターの楽しさを明らかにする','ギターの練習方法を調べ、どのようにすればギターを楽しめるのかを調査をする。','どのように練習をすればうまくなれるのか','ギターができる人にいろいろ聞いてみる 簡単な練習方法を表にまとめる','ギター、タブレット、紙、筆記用具','国語、音楽','音楽：音楽室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','9','D','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','10','D','','たくさんの練習法や筋肉の使い方、ダンスがもっと上手になるためにいっぱい研究する。','ダンスが上手になる秘密を明らかにしたい。 ダンスが上手な人の筋肉の使い方も調べてみたい。','ダンスが上手な人に聞いたり、上手な人の踊りを研究する。','筋肉のつくりについて調べる 自分に合った練習方法を見つける','ダンスが上手な人の体の使い方を調べる。','タブレット','保体、理科、英語、音楽','保体①：体上','タブレットを忘れない','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','11','D','','海について','','','自分の癖を治す！','タブレットや本を使って海の生き物を調べる','ノート？','理科？','理科：第１理科室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','12','D','','とりあえず左利きになるために練習をする。','練習すれば左足を使えるようになるかを証明したいです。','右足のホームを見てそれを左足でも同じように見よう見まねでやる。','左足を蹴れるようになる為に左足を使う。','左足でシュートを蹴り続ける。','ボール、サッカーのスパイク、ゴール。','体育','保体②：校庭','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','13','D','','勉強をする意味','勉強は将来役に立つのか、勉強をやるメリットやデメリットなど','人に聞いたことをまとめてそれによるメリット、デメリットを調べる','勉強をする意味や、将来何に役立つのかなど。','インターネットで調べたり、自分で「例えば」を考える。','タブレット','国語、数学、理科、社会…','その他：視聴覚室','','');
