INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','15','D','','深海にいる生物について！！','本研究では深海のなぞについて1％でも知る！！','ネットとかSNSで気になった情報とかを詳しく調べてみる！','まず深海の生物について調べてみる','深海の生物を調べる！！！！！','なし！','理科','理科：第１理科室','','');
