INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','3','D','','現代のパソコンと型落ちパソコンは、内部のソフトやメモリーが違うのか。','現代と昔の違いを発見する','本探求では、パソコンを家で分解して内部をシラベル','テンプレートを作る','家で分解する','特になし','社会','社会：２A教室','','');
