INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','21','D','','原宿で挑戦しやすい環境を作るにはどうすればよいか。','本探求では、シリコンバレーが発展した要因を分析して、原宿で新しい挑戦が生まれやすい環境を作るために必要な条件を調べる。','シリコンバレーと原宿を比較・分析し、挑戦しやすい環境に必要な条件を見つける。','シリコンバレーが発展した要因を調べて、原宿に取り入れられる要素を見つける。','シリコンバレーが発展した要因を調べて、その内容を原宿の現状と比較することで、原宿の強みを生かした挑戦しやすい環境づくりの具体的な方法を考える。','なし','社会','社会：２A教室','なし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','22','D','','なぜ海外の赤ちゃんをみるといやされるのか','赤ちゃんを見ると癒される理由を明らかにする','赤ちゃんの見た目や声が関係しているかを調べる','海外の赤ちゃん特有の魅力について','ネットで調べたり、実際に知り合いの海外の人の赤ちゃんと遊んで感じたことを元に調べる','','理科、家庭科','その他：視聴覚室','ない','');
