INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','8','D','','なぜユダヤ人は世界で嫌われてきたのか','ユダヤ教の信条を調べる。','イスラム教・キリスト教と比較して表にしてまとめる','一神教か多神教か、戒律の違いなどをインターネットで調べる。','インターネットで調べる','なし','社会','社会：２A教室','ユダヤ教、イスラム教、キリスト教はすべて一神教｡ヤハウェとアッラーは同一の神であるとされている。','');
